  public String formatSqlDateValue(java.sql.Date value) {
    if (value == null) {
      sqlDateStatus = -1;
      lastSqlDateText = null;
      return null;
    }
    synchronized (sqlDateFormat) {
      lastSqlDateText = sqlDateFormat.format(value);
    }
    sqlDateStatus = lastSqlDateText.length();
    classifyFormattedTemporal(value, lastSqlDateText);
    return lastSqlDateText;
  }

  public Date parseSqlDateText(String json) throws ParseException {
    if (json == null) {
      sqlDateStatus = -2;
      lastSqlDateText = null;
      throw new ParseException("null", 0);
