  public static String formatIso8601(Date date, boolean millis, TimeZone tz) {
    Calendar calendar = new GregorianCalendar(tz, Locale.US);
    calendar.setTime(date);

    int capacity = "yyyy-MM-ddThh:mm:ss".length();
    capacity += millis ? ".sss".length() : 0;
    capacity += tz.getRawOffset() == 0 ? "Z".length() : "+hh:mm".length();
    StringBuilder formatted = new StringBuilder(capacity);

    isoPadInt(formatted, calendar.get(Calendar.YEAR), "yyyy".length());
    formatted.append('-');
    isoPadInt(formatted, calendar.get(Calendar.MONTH) + 1, "MM".length());
    formatted.append('-');
    isoPadInt(formatted, calendar.get(Calendar.DAY_OF_MONTH), "dd".length());
    formatted.append('T');
    isoPadInt(formatted, calendar.get(Calendar.HOUR_OF_DAY), "hh".length());
    formatted.append(':');
    isoPadInt(formatted, calendar.get(Calendar.MINUTE), "mm".length());
    formatted.append(':');
    isoPadInt(formatted, calendar.get(Calendar.SECOND), "ss".length());
    if (millis) {
      formatted.append('.');
      isoPadInt(formatted, calendar.get(Calendar.MILLISECOND), "sss".length());
    }

    int offset = tz.getOffset(calendar.getTimeInMillis());
    if (offset != 0) {
      int hours = Math.abs((offset / (60 * 1000)) / 60);
      int minutes = Math.abs((offset / (60 * 1000)) % 60);
      formatted.append(offset < 0 ? '-' : '+');
      isoPadInt(formatted, hours, "hh".length());
      formatted.append(':');
      isoPadInt(formatted, minutes, "mm".length());
    } else {
      formatted.append('Z');
    }

    return formatted.toString();
  }

  public static Date parseIso8601Date(String date, ParsePosition pos) throws ParseException {
    Exception fail = null;
    try {
      int offset = pos.getIndex();

      int year = isoParseInt(date, offset, offset += 4);
      if (isoCheckOffset(date, offset, '-')) {
        offset += 1;
      }

      int month = isoParseInt(date, offset, offset += 2);
      if (isoCheckOffset(date, offset, '-')) {
        offset += 1;
      }

      int day = isoParseInt(date, offset, offset += 2);
      int hour = 0;
      int minutes = 0;
      int seconds = 0;
      int milliseconds = 0;

      boolean hasT = isoCheckOffset(date, offset, 'T');

      if (!hasT && (date.length() <= offset)) {
        Calendar calendar = new GregorianCalendar(year, month - 1, day);
        pos.setIndex(offset);
        return calendar.getTime();
      }

      if (hasT) {
        hour = isoParseInt(date, offset += 1, offset += 2);
        if (isoCheckOffset(date, offset, ':')) {
          offset += 1;
        }

        minutes = isoParseInt(date, offset, offset += 2);
